// Vietnamese layer for kanji. `hanviet.json` is generated by tools/importHanViet.py (Unicode Unihan, see LICENSE-DATA.md).
// `meaning-vi.json` is filled by hand: { "業": "nghề, công việc" }. Never put Hán Việt readings or translated English here.
import hanviet from "./hanviet.json";
import meaningVi from "./meaning-vi.json";

/** manual = hand-written in kanji.ts, direct = Unihan for this kanji, variant = via a reading-preserving variant (`via`). */
export type HanVietEntry = {
  hv: string[];
  status: "manual" | "direct" | "variant";
  via?: { char: string; relation: string }[];
};

export const HANVIET = hanviet.kanji as Record<string, HanVietEntry>;
export const MEANING_VI = meaningVi as Record<string, string>;
